import * as T from '../../vendor/three.module.js';
import {GLTFLoader} from '../../vendor/GLTFLoader.js';
import {DRACOLoader} from './DRACOLoader.js';
import {prepareFerrari,loadReferenceAssets,addReferenceShadow,referenceGrid} from './ferrari-reference.mjs?v=surface-compare-1';
const $=id=>document.getElementById(id),stage=document.querySelector('.stage');
const renderer=new T.WebGLRenderer({canvas:$('world'),antialias:true});const requestedRatio=Number(new URLSearchParams(location.search).get('review-dpr'));renderer.setPixelRatio(requestedRatio>=1&&requestedRatio<=1.5?requestedRatio:Math.min(devicePixelRatio,1.5));renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.85;
const scene=new T.Scene();scene.background=new T.Color('#333333');const camera=new T.PerspectiveCamera(40,1,.025,100);scene.add(referenceGrid());
let root,view='exterior',rolling=false,roll=0,steer=0,raf=0,last=0,measuring=false,abort=false,ready=false,assets,baseline=[],wheels=[],steering,steeringBase,others=[],measurements=null;
const xAxis=new T.Vector3(1,0,0),yAxis=new T.Vector3(0,1,0),q=new T.Quaternion();
function render(){renderer.render(scene,camera);}
function cameraPose(){const aspect=camera.aspect;if(view==='cockpit'){camera.fov=60;camera.position.set(-.346,1.06,.23);camera.lookAt(-.346,.89,-3);}else if(view==='four'){camera.fov=45;camera.position.set(8,6,aspect<1?-23:-14);camera.lookAt(0,.6,3);}else{camera.fov=40;camera.position.set(4.25,aspect<1?2:1.4,aspect<1?-7.5:-4.5);camera.lookAt(0,.5,0);}camera.updateProjectionMatrix();}
function resize(){if(measuring)abort=true;const b=stage.getBoundingClientRect();renderer.setSize(b.width,b.height,false);camera.aspect=b.width/b.height;cameraPose();render();}new ResizeObserver(resize).observe(stage);
function pose(){for(const w of wheels){w.pivot.rotation.y=w.front?steer*.46:0;w.node.quaternion.copy(w.base).multiply(q.setFromAxisAngle(xAxis,roll));}if(steering)steering.quaternion.copy(steeringBase).multiply(q.setFromAxisAngle(yAxis,-steer*1.92));root?.updateMatrixWorld(true);}
function audit(){let triangles=0,meshes=0;root?.traverse(o=>{if(o.isMesh&&!o.userData.referenceShadow){meshes++;triangles+=(o.geometry.index?.count||o.geometry.attributes.position.count)/3;}});return{ready,view,measuring,rolling,steer,roll,bodyColor:root?.getObjectByName('body').material.color.getHexString(),rimColor:root?.getObjectByName('rim_fl').material.color.getHexString(),camera:camera.position.toArray(),fov:camera.fov,pixelRatio:renderer.getPixelRatio(),stage:{width:stage.clientWidth,height:stage.clientHeight},triangles,meshes,drawCalls:renderer.info.render.calls,renderTriangles:renderer.info.render.triangles,memory:{...renderer.info.memory},wheels:wheels.map(w=>({name:w.node.name,front:w.front,center:w.pivot.position.toArray(),yaw:w.pivot.rotation.y,rotation:w.node.quaternion.toArray(),axis:xAxis.clone().applyQuaternion(w.base).toArray()})),steering:steering?{position:steering.position.toArray(),rotation:steering.quaternion.toArray()}:null,geometryUnchanged:baseline.every(b=>b.node.geometry===b.geometry&&b.geometry.getAttribute('position')===b.position&&b.position.version===b.version),centerRay:root?new T.Raycaster(camera.position,camera.getWorldDirection(new T.Vector3())).intersectObject(root,true).slice(0,5).map(h=>({name:h.object.name,distance:h.distance,material:h.object.material.name,transmission:h.object.material.transmission||0})):[],steeringColumnParent:root?.getObjectByName('steering_column').parent.name,noSourceTextures:true,isolated:true,cityPhysicsMirrorsIncluded:false};}
function report(){ $('inspection-state').textContent=JSON.stringify(audit());}
function setView(value){view=value;for(const ob of others)ob.visible=value==='four';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===value)));$('view-label').textContent={exterior:'원본 외관 · 공식 도장',cockpit:'원본 실내 · 임시 눈 위치',four:'동일 차량 4대 · 단순 표시 부하'}[value];cameraPose();render();report();}
function loop(now){raf=0;if(!rolling||measuring)return;if(last)roll-=Math.min(.05,(now-last)/1000)*3;last=now;pose();render();raf=requestAnimationFrame(loop);}
function stop(){rolling=false;last=0;cancelAnimationFrame(raf);raf=0;$('roll').setAttribute('aria-pressed','false');$('roll').textContent='바퀴 굴림';report();}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{if(!measuring)setView(b.dataset.view);};
$('steer').oninput=e=>{steer=Number(e.target.value);pose();render();report();};
$('roll').onclick=()=>{if(rolling)stop();else{rolling=true;$('roll').setAttribute('aria-pressed','true');$('roll').textContent='굴림 멈춤';last=0;raf=requestAnimationFrame(loop);report();}};
$('reset').onclick=()=>{stop();steer=0;roll=0;$('steer').value='0';pose();render();report();};
$('paint').onchange=e=>{root.getObjectByName('body').material.color.set(e.target.value);render();report();};
$('rim').onchange=e=>{for(const name of ['fl','fr','rl','rr'])root.getObjectByName('rim_'+name).material.color.set(e.target.value);render();report();};
const percentile=(a,p)=>a.toSorted((x,y)=>x-y)[Math.min(a.length-1,Math.floor(a.length*p))]||0;
async function sample(profile){setView(profile);let first=0,previous=0;const intervals=[],submit=[];while(true){const now=await new Promise(requestAnimationFrame);if(abort||document.hidden)throw Error('cancelled');if(!first)first=now;roll-=.05;pose();const start=performance.now();render();const elapsed=performance.now()-start;if(previous&&now-first>=1000){intervals.push(now-previous);submit.push(elapsed);}previous=now;if(now-first>=6000)break;}const median=percentile(intervals,.5);return{profile,...audit(),frames:intervals.length,medianMs:median,p95Ms:percentile(intervals,.95),fps:1000/median,over33ms:intervals.filter(x=>x>33.4).length,submitMedianMs:percentile(submit,.5)};}
$('measure').onclick=async()=>{if(measuring){abort=true;return;}const restore={view,steer,roll,paint:$('paint').value,rim:$('rim').value};stop();measuring=true;abort=false;steer=0;root.getObjectByName('body').material.color.set('#ff0000');for(const name of ['fl','fr','rl','rr'])root.getObjectByName('rim_'+name).material.color.set('#ffffff');for(const e of document.querySelectorAll('button,input,select'))e.disabled=e.id!=='measure';$('measure').textContent='측정 중단';measurements=null;$('performance-state').textContent='{}';$('results').textContent='측정 중…';$('share').value='';try{const results=[];for(const profile of ['exterior','four','cockpit']){$('status').textContent={exterior:'외관 한 대 측정 중…',four:'네 대 표시 부하 측정 중…',cockpit:'운전석 표시 측정 중…'}[profile];results.push(await sample(profile));}measurements={results,userAgent:navigator.userAgent,devicePixelRatio,renderPixelRatio:renderer.getPixelRatio(),note:'6 seconds each: 1s warm-up + 5s sample. Simple rendering only; no city, physics, mirrors, or heat test.'};$('performance-state').textContent=JSON.stringify(measurements);const text=results.map(r=>({exterior:'외관 1대',four:'외관 4대',cockpit:'운전석'})[r.profile]+': '+r.fps.toFixed(1)+' fps / 33ms 초과 '+r.over33ms+'/'+r.frames+' / p95 '+r.p95Ms.toFixed(1)+'ms').join('\n');$('results').textContent=text;$('share').value=text+'\n화면 '+stage.clientWidth+'×'+stage.clientHeight+' / 배율 '+renderer.getPixelRatio()+'\n'+navigator.userAgent;$('status').textContent='측정 완료. 아래 결과를 복사해 전달해 주세요.';}catch(e){if(e.message==='cancelled'){$('status').textContent='측정을 중단했습니다. 화면을 켜 두고 다시 실행해 주세요.';$('results').textContent='중단된 측정은 결과로 사용하지 않습니다.';}else{$('status').textContent='측정 오류가 발생했습니다.';console.error(e);}}finally{measuring=false;steer=restore.steer;roll=restore.roll;root.getObjectByName('body').material.color.set(restore.paint);for(const name of ['fl','fr','rl','rr'])root.getObjectByName('rim_'+name).material.color.set(restore.rim);pose();for(const e of document.querySelectorAll('button,input,select'))e.disabled=false;$('measure').textContent='약 20초 성능 측정';setView(restore.view);}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){abort=true;stop();}});
for(const control of document.querySelectorAll('button,input,select'))control.disabled=true;
const decoder=new DRACOLoader();decoder.setDecoderPath(new URL('./draco/',import.meta.url).href);decoder.setDecoderConfig({type:'wasm'});const loader=new GLTFLoader().setDRACOLoader(decoder);
try{const [loaded,gltf]=await Promise.all([loadReferenceAssets(),loader.loadAsync(new URL('../../assets/vehicle-compare/ferrari/ferrari.glb',import.meta.url).href)]);assets=loaded;scene.environment=assets.environment;root=prepareFerrari(gltf.scene.children[0]);root.traverse(o=>{if(o.isMesh)baseline.push({node:o,geometry:o.geometry,position:o.geometry.getAttribute('position'),version:o.geometry.getAttribute('position').version});});
 for(const name of ['fl','fr','rl','rr'])root.getObjectByName('rim_'+name).material=root.getObjectByName('rim_'+name).material.clone();
 addReferenceShadow(root,assets.shadow);scene.add(root);
 for(const [x,z]of [[-4,5],[0,5],[4,5]]){const ob=root.clone(true);ob.position.set(x,0,z);ob.visible=false;scene.add(ob);others.push(ob);}
 for(const name of ['wheel_fl','wheel_fr','wheel_rl','wheel_rr']){const node=root.getObjectByName(name),pivot=new T.Group();pivot.name=name+'_inspection_steer';pivot.position.copy(node.position);node.parent.add(pivot);pivot.add(node);node.position.set(0,0,0);wheels.push({node,pivot,base:node.quaternion.clone(),front:name.includes('_f')});}
 steering=root.getObjectByName('steering_wheel');steeringBase=steering.quaternion.clone();root.updateMatrixWorld(true);root.attach(root.getObjectByName('steering_column'));ready=true;for(const control of document.querySelectorAll('button,input,select'))control.disabled=false;resize();setView('exterior');$('measure').disabled=false;$('status').textContent='준비 완료. 외관·운전석과 바퀴 움직임을 확인할 수 있습니다.';report();
}catch(e){$('status').textContent='모델을 불러오지 못했습니다. 다시 열어 주세요.';console.error(e);}finally{decoder.dispose();}
